<?php use yii\helpers\Html;use yii\widgets\ActiveForm;$this->title='Asset Register';?><div class="toolbar"><form><input name="q" value="<?=Html::encode($q)?>" placeholder="Search property no., article, serial..."><button>Search</button></form><?=Html::a('+ Register asset',['assets','new'=>1],['class'=>'btn primary'])?></div><?php if($model):?><section class="panel formpanel"><h3><?=$model->isNewRecord?'Register':'Edit'?> asset</h3><?php $f=ActiveForm::begin(['options'=>['class'=>'gridform']]);?><?php foreach(['property_number'=>'Property Number','date_acquired'=>'Date Acquired','article'=>'Article','brand_model'=>'Brand / Model','serial_number'=>'Serial Number','quantity'=>'Quantity','unit'=>'Unit','acquisition_amount'=>'Acquisition Amount','book_value'=>'Book Value','office'=>'Office','location'=>'Location','accountable_officer'=>'Accountable Officer','condition'=>'Condition','ppe_type'=>'PPE Type','system_status'=>'System Status','tracking_notes'=>'Tracking Notes'] as $k=>$l)echo $f->field($model,$k)->textInput()->label($l);?><?=Html::submitButton('Save asset',['class'=>'btn primary'])?> <?=Html::a('Cancel',['assets'],['class'=>'btn'])?><?php ActiveForm::end();?></section><?php endif?><section class="panel tablepanel"><div class="panelhead"><h3><?=count($rows)?> records shown</h3></div><div class="scroll"><table><thead><tr><th>Property No.</th><th>Article / Model</th><th>Office / Location</th><th>Officer</th><th>Acquisition</th><th>Book Value</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=Html::encode($r->property_number)?></strong><span><?=Html::encode($r->serial_number)?></span></td><td><?=Html::encode($r->article)?><span><?=Html::encode($r->brand_model)?></span></td><td><?=Html::encode($r->office)?><span><?=Html::encode($r->location)?></span></td><td><?=Html::encode($r->accountable_officer)?></td><td>₱<?=number_format((float)$r->acquisition_amount,2)?></td><td>₱<?=number_format((float)$r->book_value,2)?></td><td><em class="badge"><?=Html::encode($r->system_status)?></em></td><td><?=Html::a('Edit',['assets','edit'=>$r->id])?></td></tr><?php endforeach?></tbody></table></div></section>
